CREATE TABLE company_settings(k VARCHAR(60) PRIMARY KEY,v TEXT);
CREATE TABLE admins(id SERIAL PRIMARY KEY,username VARCHAR(50) UNIQUE,email VARCHAR(120) UNIQUE,full_name VARCHAR(100),password_hash VARCHAR(255),role VARCHAR(30) DEFAULT 'hr_manager' CHECK(role IN('super_admin','hr_manager','payroll_manager','assessment_manager','recruitment_manager')),is_active SMALLINT DEFAULT 1);
CREATE TABLE admin_audit_logs(id SERIAL PRIMARY KEY,admin_id INT REFERENCES admins(id),action VARCHAR(255),ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employees(id SERIAL PRIMARY KEY,employee_code VARCHAR(30) UNIQUE,full_name VARCHAR(100),email VARCHAR(120) UNIQUE,mobile VARCHAR(20),joining_date DATE,status VARCHAR(20) DEFAULT 'Active' CHECK(status IN('Active','Inactive','On Leave')),login_active SMALLINT DEFAULT 1,password_hash VARCHAR(255),photo VARCHAR(255),bank_name VARCHAR(80),account_no VARCHAR(30),ifsc VARCHAR(15),pan VARCHAR(12),address TEXT,dob DATE,gender VARCHAR(10),emergency_name VARCHAR(80),emergency_phone VARCHAR(20));
CREATE TABLE attendance_records(id SERIAL PRIMARY KEY,employee_id INT REFERENCES employees(id) ON DELETE CASCADE,att_date DATE,status VARCHAR(20) CHECK(status IN('Present','Half Day','Paid Leave','Unpaid Leave','Weekly Off','Holiday','Absent')),check_in TIMESTAMP NULL,check_out TIMESTAMP NULL,source VARCHAR(10) DEFAULT 'manual',UNIQUE(employee_id,att_date));
CREATE TABLE evaluation_categories(id SERIAL PRIMARY KEY,name VARCHAR(80),description VARCHAR(255),is_active SMALLINT DEFAULT 1);
CREATE TABLE rating_scales(id SERIAL PRIMARY KEY,min_score NUMERIC(5,2),max_score NUMERIC(5,2),label VARCHAR(40),color VARCHAR(20));
CREATE TABLE employee_assessments(id SERIAL PRIMARY KEY,employee_id INT REFERENCES employees(id) ON DELETE CASCADE,category_id INT REFERENCES evaluation_categories(id),batch_title VARCHAR(100),eval_date DATE,score_percent NUMERIC(5,2),tasks_count INT,remarks TEXT,is_published SMALLINT DEFAULT 0);
CREATE TABLE candidates(id SERIAL PRIMARY KEY,candidate_code VARCHAR(30) UNIQUE,full_name VARCHAR(100),email VARCHAR(120) UNIQUE,phone VARCHAR(20),position VARCHAR(100),password_hash VARCHAR(255),is_active SMALLINT DEFAULT 1);
CREATE TABLE tests(id SERIAL PRIMARY KEY,title VARCHAR(150),instructions TEXT,duration_minutes INT DEFAULT 30,pass_percent INT DEFAULT 50,max_attempts INT DEFAULT 1,randomize SMALLINT DEFAULT 1);
CREATE TABLE candidate_test_assignments(id SERIAL PRIMARY KEY,candidate_id INT REFERENCES candidates(id) ON DELETE CASCADE,test_id INT REFERENCES tests(id),deadline TIMESTAMP NULL,status VARCHAR(30) DEFAULT 'Not Started',result_published SMALLINT DEFAULT 0);
CREATE TABLE announcements(id SERIAL PRIMARY KEY,title VARCHAR(150),body TEXT,priority VARCHAR(10) DEFAULT 'Normal',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
